#include "jacobi-1d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Halide-based initialization of A and B, with an optimized schedule.
static void init_array(int n,
                       Halide::Buffer<num_t, 1> A,
                       Halide::Buffer<num_t, 1> B) {
    Var i("i");

    Func init_A("init_A"), init_B("init_B");

    // A[i] = ((DATA_TYPE) i + 2) / n;
    // B[i] = ((DATA_TYPE) i + 3) / n;
    Expr n_val = cast<num_t>(n);
    init_A(i) = (cast<num_t>(i) + cast<num_t>(2)) / n_val;
    init_B(i) = (cast<num_t>(i) + cast<num_t>(3)) / n_val;

    // ---- Schedule for initialization ----
    // We vectorize and parallelize the 1D initialization to make good use
    // of SIMD and multiple cores, even though it runs only once.
    Target target = get_jit_target_from_environment();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // Tile size along i: chosen to have reasonable granularity for parallel
    // work while keeping overhead modest.
    const int init_tile = 4096;

    Var io("io"), ii("ii");

    init_A
        .compute_root()
        .split(i, io, ii, init_tile)   // Outer tiles of size 'init_tile'
        .parallel(io)                  // Parallelize across tiles
        .vectorize(ii, vec_width);     // Vectorize within each tile

    init_B
        .compute_root()
        .split(i, io, ii, init_tile)
        .parallel(io)
        .vectorize(ii, vec_width);

    // JIT-compile once, then realize into the provided buffers.
    init_A.compile_jit(target);
    init_B.compile_jit(target);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 1D buffers A and B of length n.
    Halide::Buffer<num_t, 1> A(n);
    Halide::Buffer<num_t, 1> B(n);

    // Initialize A and B.
    init_array(n, A, B);

    // ImageParams used as inputs to the per-time-step Halide kernels.
    ImageParam A_param(type_of<num_t>(), 1, "A_param");
    ImageParam B_param(type_of<num_t>(), 1, "B_param");

    // Var for the interior index (0 .. n-3), corresponding to i = k+1 in C.
    Var k("k");

    // Center index in the original array: i = k + 1 (i runs from 1 .. n-2).
    Expr i_center = k + 1;

    // Constant factor 0.33333 cast to num_t (as an Expr).
    Expr coeff = cast<num_t>(Expr(0.33333));

    // One Jacobi sweep: A -> B (compute B[i] from neighbors of A[i]).
    Func jacobi_A_to_B("jacobi_A_to_B");
    jacobi_A_to_B(k) =
        coeff * (A_param(i_center - 1) +
                 A_param(i_center) +
                 A_param(i_center + 1));

    // One Jacobi sweep: B -> A (compute A[i] from neighbors of B[i]).
    Func jacobi_B_to_A("jacobi_B_to_A");
    jacobi_B_to_A(k) =
        coeff * (B_param(i_center - 1) +
                 B_param(i_center) +
                 B_param(i_center + 1));

    // ---- Optimized schedules for the Jacobi sweeps ----
    //
    // We:
    //  - Split k into tiles to create coarse-grained work units.
    //  - Parallelize across tiles to use multiple cores.
    //  - Within each tile, further split and vectorize for SIMD.
    //
    // This improves cache behavior and reduces parallel overhead compared
    // to parallelizing individual scalar iterations directly.
    Target target = get_jit_target_from_environment();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // Tile size along k. Tune this for your cache / core count if desired.
    const int jacobi_tile = 8192;

    Var ko("ko"), ki("ki");
    Var kvec_outer("kvec_outer"), kvec_inner("kvec_inner");

    // Schedule for A -> B sweep.
    jacobi_A_to_B
        .compute_root()
        // First, create large tiles along k to parallelize over.
        .split(k, ko, ki, jacobi_tile)
        .parallel(ko)
        // Now split the inner tile into vector-sized chunks and scalar tail.
        .split(ki, kvec_outer, kvec_inner, vec_width)
        .vectorize(kvec_inner);

    // Schedule for B -> A sweep (identical strategy).
    jacobi_B_to_A
        .compute_root()
        .split(k, ko, ki, jacobi_tile)
        .parallel(ko)
        .split(ki, kvec_outer, kvec_inner, vec_width)
        .vectorize(kvec_inner);

    // Bind the interior [1 .. n-2] of A and B to contiguous Halide Buffers.
    // k runs from 0 .. n-3; k == 0 corresponds to element index 1.
    Halide::Buffer<num_t, 1> A_interior(A.data() + 1, n - 2);
    Halide::Buffer<num_t, 1> B_interior(B.data() + 1, n - 2);

    // JIT-compile the per-sweep kernels once with the chosen target.
    jacobi_A_to_B.compile_jit(target);
    jacobi_B_to_A.compile_jit(target);

    // Time the Jacobi iterations (the main kernel).
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // First half-step: A -> B (update B[1..n-2] from A).
        A_param.set(A);
        jacobi_A_to_B.realize(B_interior);

        // Second half-step: B -> A (update A[1..n-2] from B).
        B_param.set(B);
        jacobi_B_to_A.realize(A_interior);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the output array A to stderr (to mimic PolyBench DCE).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < n; i++) {
            std::cerr << A(i) << '\n';
        }
    }

    // Print the elapsed time (in seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
