static Target get_halide_target() {
    static Target target = get_jit_target_from_environment();
    return target;
}

// Get a reasonable SIMD width for `num_t` on this Target.
static int get_vector_width() {
    static int width = 0;
    if (width == 0) {
        Target t = get_halide_target();
        width = t.natural_vector_size(type_of<num_t>());
        if (width < 1) {
            width = 1;
        }
    }
    return width;
}

// -----------------------------------------------------------------------------
// Halide-based initialization of A and B.
// -----------------------------------------------------------------------------
static void init_array(int n,
                       Halide::Buffer<num_t, 1> A,
                       Halide::Buffer<num_t, 1> B) {
    Var i("i");

    Func init_A("init_A"), init_B("init_B");

    // A[i] = ((DATA_TYPE) i + 2) / n;
    // B[i] = ((DATA_TYPE) i + 3) / n;
    //
    // Cast numeric literals via Expr to avoid accidental type mismatches.
    Expr n_expr = cast<num_t>(Expr(n));
    init_A(i) = (cast<num_t>(i) + cast<num_t>(Expr(2))) / n_expr;
    init_B(i) = (cast<num_t>(i) + cast<num_t>(Expr(3))) / n_expr;

    // -------------------------------------------------------------------------
    // Schedule for initialization:
    // - Compute at root (single global loop).
    // - Split into tiles to expose outer parallelism and inner vectorization.
    // - Vectorize across the innermost index.
    // - Parallelize across tiles.
    // -------------------------------------------------------------------------
    const int vec = get_vector_width();
    const int tile = vec * 64;  // tuneable tile size for good cache utilization

    Var io("io"), ii("ii");

    init_A
        .compute_root()
        .split(i, io, ii, tile)
        .vectorize(ii, vec)
        .parallel(io);

    init_B
        .compute_root()
        .split(i, io, ii, tile)
        .vectorize(ii, vec)
        .parallel(io);

    // JIT-compile once with the chosen target.
    Target target = get_halide_target();
    init_A.compile_jit(target);
    init_B.compile_jit(target);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 1D buffers A and B of length n.
    Halide::Buffer<num_t, 1> A(n);
    Halide::Buffer<num_t, 1> B(n);

    // Initialize A and B (outside the timed region).
    init_array(n, A, B);

    // ImageParams used as inputs to the per-time-step Halide kernels.
    ImageParam A_param(type_of<num_t>(), 1, "A_param");
    ImageParam B_param(type_of<num_t>(), 1, "B_param");

    // Var for the interior index (0 .. n-3), corresponding to i = k+1 in C.
    Var k("k");

    // Center index in the original array: i = k + 1 (i runs from 1 .. n-2).
    Expr i_center = k + 1;

    // Constant factor 0.33333 cast to num_t.
    Expr coeff = cast<num_t>(Expr(0.33333));

    // -------------------------------------------------------------------------
    // One Jacobi sweep: A -> B (compute B[i] from neighbors of A[i]).
    // B[1..n-2] = coeff * (A[i-1] + A[i] + A[i+1])
    // -------------------------------------------------------------------------
    Func jacobi_A_to_B("jacobi_A_to_B");
    jacobi_A_to_B(k) =
        coeff * (A_param(i_center - 1) +
                 A_param(i_center) +
                 A_param(i_center + 1));

    // -------------------------------------------------------------------------
    // One Jacobi sweep: B -> A (compute A[i] from neighbors of B[i]).
    // A[1..n-2] = coeff * (B[i-1] + B[i] + B[i+1])
    // -------------------------------------------------------------------------
    Func jacobi_B_to_A("jacobi_B_to_A");
    jacobi_B_to_A(k) =
        coeff * (B_param(i_center - 1) +
                 B_param(i_center) +
                 B_param(i_center + 1));

    // -------------------------------------------------------------------------
    // Scheduling for the Jacobi sweeps
    //
    // The computation at each time step is a 1D stencil over the interior
    // indices [1 .. n-2]. We:
    //   - Bound k to this interior range to help Halide's bounds inference.
    //   - Split k into tiles to expose parallelism.
    //   - Vectorize the innermost loop at the machine's natural vector width.
