    const int tile = vec * 64;  // tuneable; 64*vec is usually a good compromise

    Var ko("ko"), ki("ki");

    jacobi_A_to_B
        .compute_root()
        .bound(k, 0, n - 2)        // k in [0 .. n-3]
        .split(k, ko, ki, tile)
        .vectorize(ki, vec)
        .parallel(ko);

